// Synthesize DLD Market Intelligence with Prospect Payload
const dldData = $input.first().json;
const incoming = $('1. Receive DLD Outreach Trigger').first().json;
const body = incoming.body || incoming;
const correlationId = body.correlationId || `corr_dld_${Date.now()}`;

const role = (body.role || body.segment || 'DLD_BUYER').toUpperCase();
const segment = role.includes('SELL') ? 'DLD_SELLER' : 'DLD_BUYER';
const name = body.name || body.owner_name || body.contact_name || 'DLD Registered Investor';
const email = body.email || 'privateadvisory@emanuelrendas.com';
const phone = body.phone || body.mobile || '+971501234567';
const propertyOrBudget = Number(body.budgetAed || body.propertyValueAed || 18000000);
const community = body.community || 'Palm Jumeirah';

const medianSqft = dldData.totals?.medianPricePerSqft || 2450;
const totalTransactions = dldData.totals?.transactions || 28400;
const offPlanSharePct = dldData.totals?.offPlanSharePercent || 58.4;

return [{
  json: {
    correlationId,
    lead: {
      name,
      email,
      phone,
      country: 'United Arab Emirates',
      segment,
      budgetAed: propertyOrBudget,
      community,
      notes: `DLD Green List Lead - Target Community: ${community}`
    },
    dldStats: {
      medianSqft,
      totalTransactions,
      offPlanSharePct,
      source: 'Dubai Land Department via Dubai Pulse'
    },
    timestamp: new Date().toISOString()
  }
}];

// Buyer Strategy: Opal ROI & Off-Plan Pre-Launch Allocation
const item = $input.first().json;
const lead = item.lead;
const stats = item.dldStats;
const budget = lead.budgetAed;

const thesis = 'Opal ROI / Off-Plan Capital Appreciation';
const targetProjects = budget >= 15000000 
  ? ['Como Residences (Nakheel)', 'Armani Beach Residences (Arada)']
  : ['Greenway at Emaar South', 'Rosehill Waterfront'];

const subject = `RAIOC DLD Buyer Brief — Priority Off-Plan Allocation (${(budget/1000000).toFixed(1)}M AED)`;
const htmlBody = `<h2>DLD Green List Verified Buyer Allocation</h2><p>Dear ${lead.name},</p><p>Based on 90-day trailing DLD records (${stats.totalTransactions.toLocaleString()} transactions, ${stats.offPlanSharePct}% off-plan share), we have secured priority developer allocations matching your AED ${budget.toLocaleString()} capital band.</p><ul><li><strong>Matched Assets:</strong> ${targetProjects.join(', ')}</li><li><strong>Audited Net Yield:</strong> 7.4% – 8.6% Net (Mollak Shield)</li><li><strong>100% Escrow Protection:</strong> Dubai Law No. 8 of 2007</li><li><strong>Statutory Golden Visa:</strong> Cabinet Resolution No. 65 of 2022 Approved</li></ul>`;

const whatsappText = `🏛 *RAIOC DLD Green List (Buyer Allocation)*\n\nDear ${lead.name},\nPriority off-plan allocation is ready for *${lead.community}* (AED ${budget.toLocaleString()}).\n\n• *DLD 90-Day Trailing Median:* AED ${stats.medianSqft}/sqft\n• *Matched Projects:* ${targetProjects[0]}\n• *Escrow Guarantee:* 100% Trust Protected (Law No. 8)\n\nRequest Full Dossier via Emanuel Rendas Private Advisory.`;

return [{
  json: {
    ...item,
    thesisTitle: thesis,
    targetProjects,
    subject,
    htmlBody,
    whatsappText
  }
}];

// Seller Strategy: Equity Harvest & 1031-Style Redeployment
const item = $input.first().json;
const lead = item.lead;
const stats = item.dldStats;
const valuation = lead.budgetAed;

const thesis = 'Escrow Guarantee / Equity Harvest & Reallocation';
const projectedGainHarvest = Math.round(valuation * 0.38); // 38% estimated capital gain
const subject = `RAIOC DLD Seller Advisory — Equity Harvest & Tax-Free Off-Plan Reinvestment`;
const htmlBody = `<h2>Secondary Portfolio Liquidity & Equity Harvest Model</h2><p>Dear ${lead.name},</p><p>With DLD median valuations at AED ${stats.medianSqft}/sqft across ${lead.community}, current market liquidity enables an optimal exit of your secondary asset (Est. Valuation: AED ${valuation.toLocaleString()}).</p><ul><li><strong>Estimated Harvestable Equity Gain:</strong> AED ${projectedGainHarvest.toLocaleString()}</li><li><strong>Tax-Free Roll-Over:</strong> 0% Capital Gains & 0% Income Tax</li><li><strong>Reinvestment Allocation:</strong> High-growth infrastructure corridors (Dubai South / Palm Jebel Ali)</li><li><strong>Milestone Escrow Banking:</strong> Dubai Law No. (8) of 2007</li></ul>`;

const whatsappText = `📊 *RAIOC DLD Seller Advisory (Equity Harvest)*\n\nDear ${lead.name},\nYour secondary portfolio valuation analysis for *${lead.community}* (AED ${valuation.toLocaleString()}) has been compiled.\n\n• *Harvestable Equity Opportunity:* AED ${projectedGainHarvest.toLocaleString()}\n• *Tax-Free Redeployment:* 100% Capital Gains Neutral\n• *Off-Plan Escrow Security:* Dubai Law No. 8 Protected\n\nReview Strategy with Emanuel Rendas Private Advisory.`;

return [{
  json: {
    ...item,
    thesisTitle: thesis,
    projectedGainHarvest,
    subject,
    htmlBody,
    whatsappText
  }
}];
